import React from "react";
import { Link, useLocation } from "react-router-dom";

/*
 Put a logo at public/assets/logo.png (or change path)
*/
export default function Header() {
  const location = useLocation();
  const navItems = [
    // "Home","The School","Admissions","Academics",
    // "Extra Curricular","Download","Gallery","Mandatory Disclosure","Contact"
    { name: "Home", path: "/" },
    { name: "The School", path: "/school" },
    { name: "Admissions", path: "/admissions" },
    { name: "Academics", path: "/academics" },
    { name: "Extra Curricular", path: "/extracurricular" },
    { name: "Download", path: "/download" },
    { name: "Gallery", path: "/gallery" },
    { name: "Mandatory Disclosure", path: "/mandatory-disclosure" },
    { name: "Contact", path: "/contact" }
  ];

  return (
    <header className="site-header">
      <div className="topbar">
        <div className="top-left">
          <img src="/assets/logo.png" alt="logo" className="logo" />
          <div className="school-meta">
            <div className="school-name">Kendriya Vidyalaya Sector-24 Noida</div>
            <div className="school-sub">CBSE Board Affiliated Co-Ed English Medium Senior Secondary School</div>
          </div>
        </div>

        
        <div className="top-right">
            <a
                className="social"
                href="#"
                onClick={(e) => {
                  e.preventDefault();
                  alert("Thank you for liking our school page! ❤️");
              }}
            >
              👍 Like
            </a>

            <a
              className="social"
              href="https://www.facebook.com/p/PM-SHRI-Kendriya-Vidyalaya-Sector-24-Noida-61565191564147/"
              target="_blank"
              rel="noopener noreferrer"
            >
              ✖ Follow
            </a>

            <a
              className="social"
              href="https://www.youtube.com/@kvnoida8950"
              target="_blank"
              rel="noopener noreferrer"
            >
              ▶ YouTube
            </a>
        </div>

      </div>

      <nav className="main-nav">
        <div className="nav-inner">
          {/* {navItems.map((t, i) => {
            const path = i===0 ? "/" : `/${t.toLowerCase().replace(/\s+/g, "-")}`;
            const active = location.pathname === path || (location.pathname === "/" && i===0);
            return (
              <Link key={t} to={path} className={`nav-item ${active ? "active" : ""}`}>
                {t}
              </Link>
            );
          })} */}
          {navItems.map((item) => {
            const active = location.pathname === item.path || (location.pathname === "/" && item.path === "/");
            return (
              <Link key={item.name} to={item.path} className={`nav-item ${active ? "active" : ""}`}>
                {item.name}
              </Link>
            );
          })}
        </div>
      </nav>
    </header>
  );
}
